// Generated by change-map. Builds the eslint-plugin-boundaries rules from architecture.json.
// Change the architecture in architecture.json (or with change-map add / allow / forbid), not here.
import boundaries from "eslint-plugin-boundaries";
import architecture from "./architecture.json" with { type: "json" };

const { root, libraries, modules, features } = architecture;
const prefix = root === "." ? "" : `${root}/`;
const groups = Object.keys(features);
// Other parts may import a part only through these files.
const ENTRY_POINTS = "!{index,server}.ts";

const part = (name) => ({ element: libraries.includes(name) ? { type: `library:${name}` } : { type: "module", captured: { module: name } } });
const feature = (group, name) => ({ element: { type: `group:${group}`, captured: { feature: name } } });

export default [
  {
    files: ["**/*.{ts,tsx}"],
    plugins: { boundaries },
    settings: {
      "boundaries/elements": [
        ...groups.map((group) => ({ type: `group:${group}`, pattern: `${prefix}${group}/*`, capture: ["feature"] })),
        ...libraries.map((name) => ({ type: `library:${name}`, pattern: `${prefix}${name}` })),
        { type: "module", pattern: `${prefix}*`, capture: ["module"] },
      ],
    },
    rules: {
      "boundaries/dependencies": [
        "error",
        {
          default: "disallow",
          policies: [
            // Each part may use the parts listed for it (and a group its own features).
            ...Object.entries(modules)
              .map(([name, uses]) => ({ from: part(name), allow: { to: [...uses.map(part), ...(groups.includes(name) ? [{ element: { type: `group:${name}` } }] : [])] } }))
              .filter((policy) => policy.allow.to.length > 0),
            // A feature may use its group, the features listed for it, and what its group may use.
            ...groups.flatMap((group) =>
              Object.entries(features[group]).map(([name, uses]) => ({
                from: feature(group, name),
                allow: { to: [part(group), ...uses.map((use) => feature(group, use)), ...(modules[group] ?? []).map(part)] },
              })),
            ),
            // Other parts only through their entry points (libraries are imported directly).
            { to: { element: { type: "module" } }, disallow: { to: { element: { type: "module", fileInternalPath: ENTRY_POINTS } } } },
            ...groups.map((group) => ({ to: { element: { type: `group:${group}` } }, disallow: { to: { element: { type: `group:${group}`, fileInternalPath: ENTRY_POINTS } } } })),
          ],
        },
      ],
    },
  },
];
